        2 => value.Value is ArticlePropertyTextValue or ArticlePropertyNumberValue or ArticlePropertyBooleanValue or ArticlePropertyDateValue or ArticlePropertyUrlValue,
        3 => value.Value is ArticlePropertySingleSelectValue or ArticlePropertyMultiSelectValue,
        4 => value.Value is ArticlePropertyArticleReferenceValue,
        _ => false
