    private ref struct PropertyReadWireReader
    {
        private readonly ReadOnlySpan<byte> _source;
        private int _offset;
        private int _facts;
        public PropertyReadWireReader(ReadOnlySpan<byte> source)
        {
            _source = source;
            _offset = 0;
            _facts = 0;
        }
        public bool IsConsumed => _offset == _source.Length;
        private ReadOnlySpan<byte> Take(int length)
        {
            if (length < 0 || length > _source.Length - _offset) throw new FormatException("property_read_wire_truncated");
            var bytes = _source.Slice(_offset, length);
            _offset += length;
            return bytes;
        }
        public byte ReadByte() => Take(1)[0];
        public bool ReadBoolean()
        {
            byte value = ReadByte();
            if (value > 1) throw new FormatException("property_read_wire_boolean");
            return value == 1;
        }
        public byte ReadEnum(ReadOnlySpan<byte> allowed)
        {
            byte value = ReadByte();
            if (!allowed.Contains(value)) throw new FormatException("property_read_wire_enum");
            return value;
        }
        public int ReadInt32(int min, int max)
        {
            int value = BinaryPrimitives.ReadInt32LittleEndian(Take(4));
            if (value < min || value > max) throw new FormatException("property_read_wire_int32");
            return value;
        }
        public long ReadInt64(long min, long max)
        {
            long value = BinaryPrimitives.ReadInt64LittleEndian(Take(8));
            if (value < min || value > max) throw new FormatException("property_read_wire_int64");
            return value;
        }
        public double ReadDouble(double min, double max)
        {
            double value = BinaryPrimitives.ReadDoubleLittleEndian(Take(8));
            if (!double.IsFinite(value) || value < min || value > max) throw new FormatException("property_read_wire_double");
            return value;
        }
        public Guid ReadGuid() => new(Take(16), bigEndian: true);
        public string ReadString(int maxChars, bool digest)
        {
            int length = ReadInt32(0, maxChars * 4);
            string value = s_propertyReadWireUtf8.GetString(Take(length));
            if (value.Length > maxChars || (digest && !IsPropertyReadWireDigest(value))) throw new FormatException("property_read_wire_string");
            return value;
        }
        public int ReadCount(int maxCount, int minimumBytes, bool facts)
        {
            int count = ReadInt32(0, maxCount);
            if (count > (_source.Length - _offset) / minimumBytes) throw new FormatException("property_read_wire_count");
            if (facts)
            {
                if (count > 40000 - _facts) throw new FormatException("property_read_wire_facts_budget");
                _facts += count;
            }
            return count;
        }
    }

    private sealed class PropertyReadWireWriter
    {
        private readonly ArrayBufferWriter<byte> _buffer = new();
        private int _facts;
        private Span<byte> Reserve(int length)
        {
            if (length < 0 || length > 8388608 - _buffer.WrittenCount) throw new ArgumentException("property_read_wire_payload_budget");
            return _buffer.GetSpan(length)[..length];
        }
        public byte[] ToArray() => _buffer.WrittenSpan.ToArray();
        public void WriteByte(byte value)
        {
            Reserve(1)[0] = value;
            _buffer.Advance(1);
        }
        public void WriteBoolean(bool value) => WriteByte(value ? (byte)1 : (byte)0);
        public void WriteEnum(int value, ReadOnlySpan<byte> allowed)
        {
            if (value is < 0 or > 255 || !allowed.Contains((byte)value)) throw new ArgumentException("property_read_wire_enum");
            WriteByte((byte)value);
        }
        public void WriteInt32(int value, int min, int max)
        {
            if (value < min || value > max) throw new ArgumentException("property_read_wire_int32");
            BinaryPrimitives.WriteInt32LittleEndian(Reserve(4), value);
            _buffer.Advance(4);
        }
        public void WriteInt64(long value, long min, long max)
        {
            if (value < min || value > max) throw new ArgumentException("property_read_wire_int64");
            BinaryPrimitives.WriteInt64LittleEndian(Reserve(8), value);
            _buffer.Advance(8);
        }
        public void WriteDouble(double value, double min, double max)
        {
            if (!double.IsFinite(value) || value < min || value > max) throw new ArgumentException("property_read_wire_double");
            BinaryPrimitives.WriteDoubleLittleEndian(Reserve(8), value);
            _buffer.Advance(8);
        }
        public void WriteGuid(Guid value)
        {
            if (!value.TryWriteBytes(Reserve(16), bigEndian: true, out int written) || written != 16) throw new ArgumentException("property_read_wire_guid");
            _buffer.Advance(16);
        }
        public void WriteString(string value, int maxChars, bool digest)
        {
            ArgumentNullException.ThrowIfNull(value);
            if (value.Length > maxChars || (digest && !IsPropertyReadWireDigest(value))) throw new ArgumentException("property_read_wire_string");
            int length = s_propertyReadWireUtf8.GetByteCount(value);
            WriteInt32(length, 0, maxChars * 4);
            if (length != 0)
            {
                s_propertyReadWireUtf8.GetBytes(value, Reserve(length));
                _buffer.Advance(length);
            }
        }
        public void WriteCount(int count, int maxCount, bool facts)
        {
            if (facts)
            {
                if (count < 0 || count > 40000 - _facts) throw new ArgumentException("property_read_wire_facts_budget");
                _facts += count;
            }
            WriteInt32(count, 0, maxCount);
        }
    }

    private static bool IsPropertyReadWireDigest(string value)
    {
        if (value.Length != 64) return false;
        foreach (char character in value) if (character is not (>= '0' and <= '9') and not (>= 'a' and <= 'f')) return false;
        return true;
    }
